const data = $input.first().json.results?.[0]?.html || $input.first().json.data;

let text = '';

if (typeof data === 'string') {
  text = data;
} else if (data && typeof data === 'object') {
  text = JSON.stringify(data, null, 2);
} else {
  text = String(data ?? '');
}

// Limit content sent to the AI
const MAX_CHARS = 30000;

if (text.length > MAX_CHARS) {
  text = text.substring(0, MAX_CHARS);
  text += '\n\n[Website content truncated for AI analysis.]';
}

return [
  {
    json: {
      website: $('Audit Input').first().json.website,
      content: text,
      scraper_used: $input.first().json.results?.[0]?.html
        ? 'crawl4ai'
        : 'firecrawl'
    }
  }
];

const output = $json.output;

const opportunities = output.opportunities || [];

const avgImpact =
  opportunities.reduce(
    (sum, o) => sum + Number(o.impact_score || 0),
    0
  ) / opportunities.length;

const avgConfidence =
  opportunities.reduce(
    (sum, o) => sum + Number(o.confidence_score || 0),
    0
  ) / opportunities.length;

const overallScore = Math.round(
  (avgImpact * 0.60) + (avgConfidence * 0.40)
);

return [
  {
    json: {
      ...$json,
      output: {
        ...output,
        overall_score: overallScore
      }
    }
  }
];

const errorMessage =
  $json.error?.message ||
  $json.error?.response?.data?.message ||
  $json.message ||
  "Website scraping failed";

return {
  json: {
    ...$json,
    website: $('Audit Input').first().json.website,
    audit_status: "FAILED",
    failure_stage: "website_scrape",
    failure_message: errorMessage,
    failed_at: new Date().toISOString()
  }
};
